-- chair-step: this file re-runs `iam.apply_rls` on twenty-two live relations, which the additive
-- allow-list refuses by name because a generator call is DDL the judge cannot read. Nothing is
-- dropped, renamed or rewritten: every policy is REGENERATED by the platform's own generator from
-- the platform's own registry, exactly as `iam.apply_rls` regenerates it on any other day. The one
-- thing that changes is the ANSWER the generator gives, because eleven tokens are reclassified from
-- `organization` to `confidential`. The inverse is
-- migrations/inverse/fix7b_a_list_of_people_is_never_platform_content_down.sql and puts the eleven
-- classes back and regenerates all twenty-two again.
--
-- lane: FIX-7B (the seventh-pass verdict's privacy defect)
--
-- FIX-7B — A LIST OF PEOPLE IS NEVER PLATFORM CONTENT.
--
-- THE DEFECT, MEASURED ON THE MAIN DATABASE 2026-09-20 FROM A REAL PERSON'S SEAT
-- (`role authenticated`, `request.jwt.claims` = test@test.com, an ordinary member of
-- fifteen organizations, none of them the platform's own tenant):
--
--     test@test.com reads 950 parties, 948 contact media, across 5 organizations
--
-- 941 of those parties and 942 of those contact media belong to ONE organization she is not a
-- member of and whose name she cannot even read: `Matrx System`, the platform's own tenant. They
-- are real named people with real email addresses and real phone numbers. Every signed-in account
-- on the platform could read all of them. The seventh-pass verdict saw the same thing from the
-- other end — a brand-new organization's share dialog listing "people from all over the database"
-- and a CRM reporting 454 contacts in an organization that has never had one added.
--
-- WHY. `crm.party` is classed `organization`, and db-rules §6e gives that class a lane that asks
-- about no membership, no role and no grant at all:
--
--     organization_id in (select so.organization_id from iam.system_orgs so where so.global_readable)
--
-- That lane exists so PLATFORM CONTENT — builtin agents, system prompts, default templates — is
-- readable by everybody, and it is right for content. `iam.class_lanes` already decides whether a
-- token gets it (`platform_admin_lane`/`org_role_lane` and the §6e arm are `organization` and
-- `public` only; DD-185 narrowed it from unconditional for exactly this reason). Nobody ever
-- decided `crm.party`'s class: its own `data_class_reason` says it was back-filled by
-- `platform.derive_data_class` from what the table happened to look like. So a table of real named
-- people inherited the lane written for platform content, and then 941 people were written into
-- the platform's own tenant.
--
-- THE CLASS, NOT THE INSTANCE. Every relation that holds or names a natural person is
-- `confidential`: the class that keeps the owner lane, ordinary sharing and the ORGANISATION
-- MEMBER lane — so nothing a member of the organization could read is taken away — and drops the
-- three lanes that reach ACROSS organizations: the global-readable system-org lane, the platform
-- admin lane and the share-link lane. Measured in a rolled-back transaction before this file was
-- written:
--
--     BEFORE: test@test.com reads 950 parties, 948 contact media, across 5 organizations
--     AFTER:  test@test.com reads   9 parties,   6 contact media, across 4 organizations,
--             0 from the system tenant
--     AFTER:  admin still reads all 6 parties in his own Workspace
--
-- WHAT KEEPS IT CLOSED. Two censuses, both queries over the live catalogue rather than a list of
-- names, both read by `pnpm check:people-lists-stay-in-your-organizations`:
--
--   · `iam.people_lists_a_non_member_can_read()` — a relation this file calls personal whose live
--     SELECT policy still carries the §6e arm. Zero after this file.
--   · `iam.people_shaped_relations_with_no_verdict()` — a relation that LOOKS personal (it has a
--     person's name or contact detail as a column, or a foreign key into `crm.party`) and which
--     `iam.personal_data_relations()` has never ruled on. Zero after this file, and the next
--     people-shaped table somebody adds turns it red until somebody rules on it.

-- ─────────────────────────────────────────────────────────────────────────────────────────────
-- 1. THE RULING. A function, not a table: which relations hold personal data is a RULE, reviewed
--    in git and the same on every database, never rows an operator can quietly edit. `is_personal`
--    is false only where a column that LOOKS like a person's contact detail is in fact a
--    business's published one — and it still has to say why.
-- ─────────────────────────────────────────────────────────────────────────────────────────────
create or replace function iam.personal_data_relations()
  returns table (relation text, is_personal boolean, why text)
  language sql
  immutable
as $$
  select * from (values
    ('crm.party',                  true,  'real named people: display_name, first_name, last_name'),
    ('crm.contact_medium',         true,  'the email addresses and phone numbers themselves, in value_raw'),
    ('crm.party_contact_point',    true,  'joins a person to their email address or phone number'),
    ('crm.address',                true,  'where a person lives or works'),
    ('crm.affiliation',            true,  'who a person works for'),
    ('crm.contact_candidate',      true,  'a person we think we have found, by name'),
    ('crm.merge_candidate',        true,  'two people we think are one person'),
    ('crm.party_merge',            true,  'the record that two people were made one'),
    ('crm.interaction',            true,  'what was said to a named person and when'),
    ('crm.deal',                   true,  'a deal, by the people and company it names'),
    ('crm.enrichment_call',        true,  'what a provider was asked about a named person'),
    ('crm.blocklist_entry',        true,  'a person who asked never to be contacted again'),
    ('crm.outreach_list_member',   true,  'which named people are on a sending list'),
    ('crm.sending_event',          true,  'what was sent to a named person, and whether they opened it'),
    ('esign.envelope_signer',      true,  'a signer''s own email, full name and phone'),
    ('esign.campaign_member',      true,  'a campaign member''s own email and full name'),
    ('commerce.print_order',       true,  'the contact email an order is delivered against'),
    ('platform.outcome_event',     true,  'an outcome recorded against a named person'),
    -- Ruled NOT personal, each with the reason, because a census with no verdict rots into a
    -- list of names nobody re-reads.
    ('crm.registry_source',        false, 'contact_email is a public registry''s own published address, not a person''s'),
    ('web.business_location',      false, 'a business''s published address, phone and email, drawn on public marketing pages'),
    ('seo.coverage_mention',       false, 'a mention of a BRAND in coverage; it names no person')
  ) as t(relation, is_personal, why);
$$;

comment on function iam.personal_data_relations() is
  'FIX-7B: which relations hold or name a natural person, and the reason for each. Read by iam.people_lists_a_non_member_can_read() and iam.people_shaped_relations_with_no_verdict().';

-- ─────────────────────────────────────────────────────────────────────────────────────────────
-- 2. THE CENSUS THAT MUST BE ZERO. A personal relation whose live SELECT policy still carries the
--    §6e global-readable system-organization arm — the arm that asks about no membership, no role
--    and no grant.
-- ─────────────────────────────────────────────────────────────────────────────────────────────
create or replace function iam.people_lists_a_non_member_can_read()
  returns table (relation text, policy_name text, why text)
  language sql
  stable
  security definer
  set search_path to 'pg_catalog', 'public'
as $$
  select r.relation,
         p.polname::text,
         r.why
    from iam.personal_data_relations() r
    join pg_catalog.pg_class c on c.oid = to_regclass(r.relation)
    join pg_catalog.pg_policy p on p.polrelid = c.oid
   where r.is_personal
     and p.polcmd in ('r', '*')
     -- the §6e arm, without the super-admin wall in front of it
     and pg_catalog.pg_get_expr(p.polqual, p.polrelid) like '%system_orgs%'
     and pg_catalog.pg_get_expr(p.polqual, p.polrelid) not like '%is_super_admin%system_orgs%'
   order by 1, 2;
$$;

comment on function iam.people_lists_a_non_member_can_read() is
  'FIX-7B census: a relation of people whose read policy still admits every signed-in account through the global-readable system organization. Must be empty.';

-- Its door row, in the same transaction (DD-223, provision_shape_guard): a SECURITY DEFINER
-- function runs as `postgres`, so somebody has to say IN DATA who may call it.
insert into platform.client_callable_door
  (schema_name, function_name, identity_args, identity_argtypes, reason, declared_by,
   non_client_lane, signed_in_callers, anonymous_callers)
values
  ('iam', 'people_lists_a_non_member_can_read', '',
   array[]::oid[],
   'A census over the catalogue only: it reads pg_policy and iam.personal_data_relations() and takes no entity id at all, so there is nothing to check a caller against. It is read by the guard pnpm check:people-lists-stay-in-your-organizations, which connects as our own login role.',
   'FIX-7B',
   'server_only: the release guard scripts/check-people-lists-stay-in-your-organizations.ts reads it over a direct Postgres connection as our own login role. No client ever calls it: it answers a question about the SHAPE of the database, not about anybody''s data, and a client that could ask it would learn which tables the platform considers personal.',
   false, false)
on conflict do nothing;

-- ─────────────────────────────────────────────────────────────────────────────────────────────
-- 3. THE CENSUS THAT MAKES IT GROW. A relation that LOOKS personal and which nobody has ruled on.
--    Derived from the catalogue — a person's name or contact detail as a column, or a foreign key
--    into crm.party — so the next people-shaped table somebody builds cannot arrive unnoticed.
-- ─────────────────────────────────────────────────────────────────────────────────────────────
create or replace function iam.people_shaped_relations_with_no_verdict()
  returns table (relation text, why text)
  language sql
  stable
  security definer
  set search_path to 'pg_catalog', 'public'
as $$
  with person_col as (
    select distinct a.attrelid as oid
      from pg_catalog.pg_attribute a
     where a.attnum > 0 and not a.attisdropped
       and a.attname in ('email','phone','mobile','first_name','last_name','full_name',
                         'given_name','family_name','person_name','contact_email','contact_name',
                         'contact_phone','email_address','phone_number')
  ), party_fk as (
    select distinct k.conrelid as oid
      from pg_catalog.pg_constraint k
     where k.contype = 'f' and k.confrelid = to_regclass('crm.party')
  ), has_the_arm as (
    select distinct p.polrelid as oid
      from pg_catalog.pg_policy p
     where p.polcmd in ('r', '*')
       and pg_catalog.pg_get_expr(p.polqual, p.polrelid) like '%system_orgs%'
       and pg_catalog.pg_get_expr(p.polqual, p.polrelid) not like '%is_super_admin%system_orgs%'
  )
  select n.nspname || '.' || c.relname,
         case when pc.oid is not null and pf.oid is not null then 'a person''s own column, and a foreign key into crm.party'
              when pc.oid is not null then 'a person''s own column'
              else 'a foreign key into crm.party' end
    from has_the_arm h
    join pg_catalog.pg_class c on c.oid = h.oid
    join pg_catalog.pg_namespace n on n.oid = c.relnamespace
    left join person_col pc on pc.oid = h.oid
    left join party_fk pf on pf.oid = h.oid
   where (pc.oid is not null or pf.oid is not null)
     and not exists (select 1 from iam.personal_data_relations() r
                      where r.relation = n.nspname || '.' || c.relname)
   order by 1;
$$;

comment on function iam.people_shaped_relations_with_no_verdict() is
  'FIX-7B census: a relation that looks like people and that iam.personal_data_relations() has never ruled on. Must be empty — rule on it, do not delete the census.';

-- Its door row, same transaction, same reason as the census above.
insert into platform.client_callable_door
  (schema_name, function_name, identity_args, identity_argtypes, reason, declared_by,
   non_client_lane, signed_in_callers, anonymous_callers)
values
  ('iam', 'people_shaped_relations_with_no_verdict', '',
   array[]::oid[],
   'A census over the catalogue only: it reads pg_attribute, pg_constraint, pg_policy and iam.personal_data_relations() and takes no entity id at all, so there is nothing to check a caller against.',
   'FIX-7B',
   'server_only: the release guard scripts/check-people-lists-stay-in-your-organizations.ts reads it over a direct Postgres connection as our own login role. No client ever calls it: it answers a question about the SHAPE of the database, not about anybody''s data.',
   false, false)
on conflict do nothing;

-- ─────────────────────────────────────────────────────────────────────────────────────────────
-- 4. THE RECLASSIFICATION. Eleven tokens whose rows hold or name natural people. The seven
--    components of `party` (address, affiliation, contact_candidate, interaction, merge_candidate,
--    party_merge, party_contact_point) need no row of their own: `iam.class_lanes` already
--    resolves a component's class from its composition parent, so they follow `party` the moment
--    it moves — but their POLICY TEXT is generated, so every one of them is regenerated below.
-- ─────────────────────────────────────────────────────────────────────────────────────────────
update platform.entity_types
   set data_class = 'confidential',
       data_class_reason = 'FIX-7B (2026-09-20): holds or names a natural person, so it is not '
                           || 'platform content and may not carry the db-rules §6e global-readable '
                           || 'system-organization lane. Measured leak: 941 named people and 942 '
                           || 'contact media in the platform tenant readable by every signed-in '
                           || 'account. `confidential` keeps the owner, sharing and organization-'
                           || 'member lanes, so no member of the organization loses anything.'
 where is_active
   and token in ('party','contact_medium','crm_blocklist_entry','crm_deal','crm_enrichment_call',
                 'commerce_print_order','platform_outcome_event','crm_outreach_list',
                 'crm_sending_identity','esign_campaign','esign_envelope');

-- ─────────────────────────────────────────────────────────────────────────────────────────────
-- 5. REGENERATE. The generator is the platform's own; this file only asks it to run again now
--    that the registry says something different. A token the generator refuses is a hard failure,
--    never a skip: a half-regenerated privacy fix is worse than none.
-- ─────────────────────────────────────────────────────────────────────────────────────────────
do $$
declare r record;
begin
  for r in
    select et.schema_name as s, et.table_name as t, et.token as k, et.rls_variant as v
      from platform.entity_types et
     where et.is_active
       and et.token in ('party','contact_medium','crm_blocklist_entry','crm_deal',
                        'crm_enrichment_call','commerce_print_order','platform_outcome_event',
                        'crm_outreach_list','crm_sending_identity','esign_campaign','esign_envelope',
                        'crm_address','crm_affiliation','crm_contact_candidate','crm_interaction',
                        'crm_merge_candidate','crm_party_merge','party_contact_point',
                        'crm_outreach_list_member','crm_sending_event','esign_campaign_member',
                        'esign_envelope_signer')
     order by et.schema_name, et.table_name
  loop
    perform iam.apply_rls(r.s, r.t, r.k, r.v);
  end loop;
end $$;

-- ─────────────────────────────────────────────────────────────────────────────────────────────
-- 6. THE FILE PROVES ITSELF. If either census is non-empty when this file finishes, the file
--    failed and the transaction must not commit.
-- ─────────────────────────────────────────────────────────────────────────────────────────────
do $$
declare n_open int; n_unruled int; v_names text;
begin
  select count(*) into n_open from iam.people_lists_a_non_member_can_read();
  if n_open > 0 then
    select string_agg(relation || ' (' || policy_name || ')', ', ')
      into v_names from iam.people_lists_a_non_member_can_read();
    raise exception 'FIX-7B: % people list(s) still readable by a non-member after this file: %',
      n_open, v_names;
  end if;
  select count(*) into n_unruled from iam.people_shaped_relations_with_no_verdict();
  if n_unruled > 0 then
    select string_agg(relation || ' — ' || why, ', ')
      into v_names from iam.people_shaped_relations_with_no_verdict();
    raise exception 'FIX-7B: % people-shaped relation(s) nobody has ruled on: %', n_unruled, v_names;
  end if;
  raise notice 'FIX-7B: both censuses are zero.';
end $$;
